style.css:
@-moz-document domain("roblox.com") {
/* Target RoGold background wrappers and layout anchors directly */
    html, 
    body, 
    #wrap,
    #container-main,
    .content, 
    .dark-theme, 
    .light-theme,
    .rbx-body,
    #app-container,
    div[class*="theme"],
    div[class*="Theme"],
    [class*="rogold"],
    [id*="rogold"],
    .ropro-theme-container {
        background-image: url("https://assets.userstyles.org/assets_packs/type=style/user_id=4969048/screenshot_abfe72ec-fb5f-4f67-bcd8-226c5633f3f9.webp") !important;
        background-color: transparent !important;
        background-size: cover !important;
        background-attachment: fixed !important;
        background-position: center !important;
        background-repeat: no-repeat !important;
    }
}
